package com.coffeeshop.repository;import com.coffeeshop.dto.DiscountCommands;import com.coffeeshop.exception.DatabaseException;import com.coffeeshop.model.DiscountModels;import javax.sql.DataSource;import java.sql.*;import java.util.*;public final class JdbcDiscountRepository implements DiscountRepository{private final DataSource ds;public JdbcDiscountRepository(DataSource d){ds=Objects.requireNonNull(d);}public List<DiscountModels.Discount>find(String search,Boolean active){String q="SELECT discount_id,discount_code,discount_name,discount_type,discount_value,valid_from,valid_until,is_active,row_version FROM dbo.discounts WHERE (? IS NULL OR is_active=?) AND (?='' OR discount_code LIKE ? OR discount_name LIKE ?) ORDER BY discount_name";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(q)){if(active==null){s.setNull(1,Types.BIT);s.setNull(2,Types.BIT);}else{s.setBoolean(1,active);s.setBoolean(2,active);}String x=search==null?"":search.trim(),like="%"+x+"%";s.setString(3,x);s.setString(4,like);s.setString(5,like);try(ResultSet r=s.executeQuery()){List<DiscountModels.Discount>out=new ArrayList<>();while(r.next()){Timestamp a=r.getTimestamp(6),b=r.getTimestamp(7);out.add(new DiscountModels.Discount(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getBigDecimal(5),a==null?null:a.toLocalDateTime(),b==null?null:b.toLocalDateTime(),r.getBoolean(8),r.getBytes(9)));}return List.copyOf(out);}}catch(SQLException e){throw fail("Unable to load discounts.",e);}}public long save(DiscountCommands.Save q){String sql=q.id()==null?"INSERT dbo.discounts(discount_code,discount_name,discount_type,discount_value,valid_from,valid_until,is_active) VALUES(?,?,?,?,?,?,?)":"UPDATE dbo.discounts SET discount_code=?,discount_name=?,discount_type=?,discount_value=?,valid_from=?,valid_until=?,is_active=?,updated_at=SYSUTCDATETIME() WHERE discount_id=? AND row_version=?";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){s.setString(1,q.code());s.setString(2,q.name());s.setString(3,q.type());s.setBigDecimal(4,q.value());time(s,5,q.validFrom());time(s,6,q.validUntil());s.setBoolean(7,q.active());if(q.id()!=null){s.setLong(8,q.id());s.setBytes(9,q.version());one(s.executeUpdate());return q.id();}s.executeUpdate();return key(s);}catch(SQLException e){throw fail("Unable to save discount. Check that its code is unique.",e);}}public void setActive(long id,boolean active,byte[]v){try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement("UPDATE dbo.discounts SET is_active=?,updated_at=SYSUTCDATETIME() WHERE discount_id=? AND row_version=?")){s.setBoolean(1,active);s.setLong(2,id);s.setBytes(3,v);one(s.executeUpdate());}catch(SQLException e){throw fail("Unable to update discount.",e);}}private static void time(PreparedStatement s,int i,java.time.LocalDateTime v)throws SQLException{if(v==null)s.setNull(i,Types.TIMESTAMP);else s.setTimestamp(i,Timestamp.valueOf(v));}private static void one(int n){if(n!=1)throw new IllegalStateException("Discount changed. Refresh and try again.");}private static long key(PreparedStatement s)throws SQLException{try(ResultSet r=s.getGeneratedKeys()){if(!r.next())throw new SQLException("Generated key unavailable");return r.getLong(1);}}private static DatabaseException fail(String m,Exception e){return new DatabaseException(m,e);}}
